export const WRITTEN_DIGITAL_COMM_ACTIVITIES = [
{n:1,type:"mcq",micro:"Tujuan pesan tertulis",q:"Sebelum menulis pesan penting, hal pertama yang perlu jelas:",options:["Apa yang aku ingin pembaca ketahui atau lakukan setelah membaca ini?","Emoji apa yang akan kupakai supaya pesannya terlihat lucu bagi pembaca","Berapa panjang pesan agar terlihat serius dan penuh usaha bagi pembaca"],answer:0,explain:"Pesan yang jelas dimulai dari tujuan yang jelas. Kalau kamu tidak tahu maunya apa, pembaca juga bingung.",hint:"Tujuan dulu, atau emoji dulu?"},
{n:2,type:"mcq",micro:"Nada hilang di teks",q:"Kelemahan utama komunikasi tertulis dibanding tatap muka:",options:["Lebih cepat dipahami karena pesan teks pendek dan langsung ke inti","Tidak ada nada suara & ekspresi wajah, jadi maksud mudah disalahtafsirkan","Terlalu jelas sehingga pembaca merasa digurui dan tersinggung"],answer:1,explain:"Kalimat 'ya, terserah kamu' bisa terbaca santai atau ketus. Di teks, kamu harus lebih hati-hati memilih kata.",hint:"Nada & wajah hilang, atau terlalu jelas?"},
{n:3,type:"mcq",micro:"Kalimat pembuka pesan",q:"Untuk pesan permintaan ke guru, pembuka yang jelas:",options:["'Bu.' lalu menunggu balasan tanpa menyebut siapa kamu atau keperluanmu","'p' (satu huruf) lalu menunggu ibu guru membalas dulu sebelum menjelaskan","'Selamat sore Bu, saya Andi kelas 8B. Saya ingin menanyakan soal tugas IPA.'"],answer:2,explain:"Sebut siapa kamu + tujuan pesan di awal. 'p' atau 'Bu.' tanpa isi membuang waktu kedua pihak.",hint:"Identitas + tujuan, atau 'p'?"},
{n:4,type:"mcq",micro:"Langsung ke inti",q:"Dalam pesan singkat, sebaiknya kamu...",options:["Sampaikan inti/permintaan lebih dulu, baru detail bila perlu","Cerita panjang dulu dari awal kejadian, baru inti pesan di kalimat terakhir","Tak menyebut inti pesan, supaya pembaca menebak sendiri keinginanmu"],answer:0,explain:"Pembaca sering memindai. Menaruh inti di depan memastikan pesan tersampaikan meski mereka tidak baca sampai habis.",hint:"Inti di depan, atau di akhir setelah cerita panjang?"},
{n:5,type:"mcq",micro:"Membaca ulang sebelum kirim",q:"Kebiasaan membaca ulang pesan penting sebelum mengirim berguna untuk...",options:["Tidak perlu, langsung kirim saja karena pesan teks tidak mungkin dipermasalahkan orang","Mengecek apakah maksudnya bisa disalahpahami, ada yang kurang, atau nadanya terdengar kasar","Membuang waktu karena pembaca akan memahami maksudmu dengan sendirinya tanpa dicek"],answer:1,explain:"Di teks tidak ada nada untuk menyelamatkan kalimat yang salah tafsir. Baca ulang menangkapnya sebelum terlambat.",hint:"Cek makna & nada, atau kirim langsung?"},
{n:6,type:"mcq",micro:"Kapital semua",q:"Menulis PESAN DENGAN HURUF KAPITAL SEMUA biasanya terbaca sebagai...",options:["Sopan & formal","Lebih jelas","Berteriak atau marah"],answer:2,explain:"Di dunia digital, kapital semua = berteriak. Pakai kapital wajar untuk awal kalimat & nama.",hint:"Berteriak, atau sopan?"},
{n:7,type:"mcq",micro:"Tanda baca & kejelasan",q:"Pesan tanpa tanda baca sama sekali ('oke besok jadi kan jam berapa di mana') sering...",options:["Sulit dibaca & membingungkan; titik/koma membantu pembaca","Terlihat santai dan keren, jadi pembaca langsung paham","Lebih cepat dibaca daripada pesan bertanda baca lengkap"],answer:0,explain:"Tanda baca adalah jeda bagi mata pembaca. Beberapa titik membuat pesan jauh lebih mudah dicerna.",hint:"Membingungkan, atau keren?"},
{n:8,type:"mcq",micro:"Nada ramah di teks",q:"Cara membuat pesan teks terdengar ramah tanpa bertele-tele:",options:["Emoji di setiap kata supaya terlihat ramah dan ceria, tanpa perlu menulis kalimat lengkap","Sapaan singkat, kata 'tolong'/'makasih', kalimat lengkap, & emoji secukupnya bila sesuai konteks","Tanpa sapaan dan langsung menuntut, supaya pesannya singkat padat dan tidak membuang waktu pembaca"],answer:1,explain:"Sedikit kehangatan ('Hai, boleh minta tolong...') mencegah pesan terbaca dingin atau memerintah.",hint:"Sapaan + tolong/makasih, atau menuntut langsung?"},
{n:9,type:"order",micro:"Menulis pesan permintaan",q:"Urutkan bagian pesan permintaan yang jelas.",items:["Sapaan & identitas bila perlu","Konteks singkat: kenapa kamu menghubungi","Permintaan yang jelas & spesifik","Ucapan terima kasih / penutup"],answer:[0,1,2,3],explain:"Sapa → konteks → permintaan spesifik → terima kasih. Pembaca langsung tahu harus berbuat apa.",hint:"Apa yang perlu diketahui pembaca sebelum permintaanmu?"},
{n:10,type:"mcq",micro:"Balas cepat vs balas baik",q:"Untuk pesan yang butuh jawaban dipikirkan, lebih baik...",options:["Membalas kilat dengan jawaban seadanya supaya pengirim tahu kamu sigap meski belum dipikirkan","Tak membalas dan berharap pengirimnya lupa pada pertanyaan itu, sehingga tak perlu berpikir","Balas 'Aku baca ya, nanti aku jawab setelah kupikir' daripada membalas asal cepat"],answer:2,explain:"Mengakui pesan + menyebut kapan akan menjawab lebih menghormati daripada balasan buru-buru atau diam.",hint:"Akui + janji balas, atau asal cepat / diam?"},
{n:11,type:"tf",micro:"Teks mudah salah tafsir",q:"Benar atau Salah: Karena teks tidak membawa nada suara & ekspresi wajah, pesan yang bermaksud bercanda atau netral bisa terbaca sebagai serius atau kasar oleh penerima.",answer:true,explain:"Inilah kenapa banyak pertengkaran chat lahir dari 'nada yang hilang'. Pilih kata dengan hati-hati & konfirmasi bila ragu.",hint:"Teks bisa salah tafsir, atau selalu jelas?"},
{n:12,type:"tf",micro:"Panjang = jelas?",q:"Benar atau Salah: Semakin panjang & rinci sebuah pesan tertulis, semakin pasti maksudmu tersampaikan dengan jelas.",answer:false,explain:"Sebaliknya, pesan yang terlalu panjang & berbelit sering membuat inti terkubur. Pesan yang ringkas & terstruktur biasanya lebih jelas.",hint:"Panjang = jelas, atau bisa mengubur inti?"},
{n:13,type:"mcq",micro:"Pesan ke grup",q:"Menulis di grup chat agar tidak tenggelam & mudah ditanggapi:",options:["Satu pesan berisi inti + detail penting, sebut siapa yang perlu bertindak, hindari mengirim 10 pesan pendek beruntun","Kirim tiap kata sebagai pesan terpisah supaya notifikasinya berbunyi berkali-kali dan dibaca anggota, walau terasa mengganggu","Tulis satu paragraf panjang tanpa jeda baris, tanpa menyebut siapa yang perlu bertindak, lalu tunggu ada yang membalas"],answer:0,explain:"Notifikasi beruntun mengganggu; paragraf tanpa jeda sulit dibaca di layar kecil. Satu pesan terstruktur menang.",hint:"Satu pesan terstruktur, atau spam pendek?"},
{n:14,type:"mcq",micro:"Menulis email/pesan formal",q:"Untuk pesan formal (ke guru, panitia, orang yang belum dikenal):",options:["Tanpa sapaan dan tanpa nama pengirim, langsung ke pokok permintaan saja","Pakai sapaan lengkap, bahasa baku secukupnya, kalimat lengkap, & tutup dengan nama","Pakai bahasa dan singkatan seperti ke teman dekat ('bro', 'wkwk', 'gpp deh') supaya akrab"],answer:1,explain:"Sesuaikan tingkat formalitas dengan penerima. Terlalu santai ke orang yang tepat bisa terkesan kurang menghormati.",hint:"Sesuaikan formalitas, atau selalu gaya teman?"},
{n:15,type:"mcq",micro:"Emoji & konteks",q:"Emoji dalam pesan...",options:["Wajib ada di setiap pesan, termasuk pesan formal kepada guru, supaya pesan terasa ramah dan ceria bagi penerima","Terlihat tidak profesional di mana pun dipakai, sehingga sebaiknya tak dipakai dalam konteks apa saja lagi","Bisa membantu menyampaikan nada di konteks santai, tapi sebaiknya hemat/tidak dipakai di pesan formal atau serius"],answer:2,explain:"Emoji adalah pengganti sebagian nada yang hilang. Cocok untuk teman; kurang cocok untuk surat resmi atau kabar duka.",hint:"Bantu nada di konteks santai, atau selalu wajib / selalu buruk?"},
{n:16,type:"mcq",micro:"Menjawab yang ditanya",q:"Temanmu bertanya 'Kumpul tugasnya kapan?'. Balasan paling jelas:",options:["'Jumat, sebelum jam 12.'","'Kamu nggak dengerin tadi?'","(cerita tentang tugas tanpa tanggal)"],answer:0,explain:"Jawab pertanyaannya dulu. Komentar atau cerita bisa ditambahkan setelahnya kalau perlu.",hint:"Jawab yang ditanya, atau menyindir / bercerita?"},
{n:17,type:"mcq",micro:"Subjek/judul pesan",q:"Menulis judul email atau baris pertama pesan yang informatif:",options:["(judul kosong, isi pesan langsung ditulis di badan email panjang)","'Permintaan izin tidak masuk 5 Sept - Andi 8B' (langsung tahu isinya)","'Halo' saja (judul yang tidak menjelaskan isi dari emailnya)"],answer:1,explain:"Judul/pembuka yang informatif membantu penerima menilai kepentingan & menemukan pesan lagi nanti.",hint:"Ringkas isi di judul, atau 'halo' / kosong?"},
{n:18,type:"mcq",micro:"Menunggu jawaban",q:"Kamu mengirim pesan & belum dibalas beberapa jam. Sikap yang wajar:",options:["Kirim '?' berkali-kali setiap 5 menit sampai dibalas, supaya orangnya sadar bahwa pesanmu mendesak untuk dijawab","Langsung menyimpulkan bahwa mereka sengaja mengabaikanmu & marah, lalu membalasnya dengan tidak menyapa mereka lagi","Beri waktu; orang punya kesibukan. Kirim pengingat sopan setelah waktu yang wajar bila memang mendesak"],answer:2,explain:"Belum dibalas jarang berarti diabaikan. Kesabaran + pengingat sopan bila perlu lebih baik daripada spam atau curiga.",hint:"Beri waktu + pengingat sopan, atau spam '?' / marah?"},
{n:19,type:"mcq",micro:"Menulis dengan pembaca di benak",q:"Menulis pesan yang baik berarti membayangkan...",options:["Bagaimana pembaca akan membacanya: apakah jelas? apakah nadanya oke? apakah ada yang kurang?","Hanya apa yang ingin kamu keluarkan dari kepalamu saat ini, tanpa perlu memikirkan siapa yang akan membacanya","Bagaimana membuat pesanmu terdengar paling pintar & paling berwibawa dibandingkan pesan-pesan yang lain di grup"],answer:0,explain:"Tulisan yang berpusat pada pembaca ('apa yang mereka butuhkan untuk paham & bertindak') selalu lebih efektif.",hint:"Bayangkan pengalaman pembaca, atau curahkan isi kepalamu?"},
{n:20,type:"open",micro:"Menulis pesan yang jelas",q:"Kamu perlu menulis pesan ke wali kelas: kamu tidak bisa ikut kegiatan hari Sabtu karena ada acara keluarga, dan ingin tahu apakah ada tugas pengganti. Tulis pesannya (lengkap, sopan, jelas), lalu jelaskan bagian-bagiannya.",explain:"Jawaban baik menghasilkan pesan yang: sapaan + identitas, inti + alasan jujur di awal, permintaan spesifik (izin + tugas pengganti), penutup terima kasih + nama, bahasa sopan/formal sesuai penerima — lalu menjelaskan fungsi tiap bagian dan menyebut membaca ulang.",hint:"Sapaan+identitas, inti+alasan di awal, permintaan spesifik, penutup terima kasih+nama, cek ulang.",sample:"Pesan: 'Selamat sore, Bu Rina. Saya Dina dari kelas 8A. Saya ingin menyampaikan bahwa hari Sabtu, 7 September, saya tidak dapat mengikuti kegiatan kelas karena ada acara keluarga yang tidak bisa saya tinggalkan. Saya mohon izin. Kalau ada tugas atau materi pengganti yang perlu saya kerjakan, mohon informasinya, Bu. Terima kasih. — Dina, 8A' Penjelasan bagian: (1) Sapaan + identitas ('Selamat sore, Bu Rina. Saya Dina dari 8A') supaya guru langsung tahu siapa yang menghubungi. (2) Inti pesan disampaikan jelas di awal (tidak bisa ikut kegiatan Sabtu 7 September) beserta alasan singkat yang jujur. (3) Permintaan yang spesifik: izin + menanyakan tugas pengganti. (4) Penutup: terima kasih + nama, karena ini pesan formal ke guru. Sebelum mengirim, saya baca ulang untuk memastikan tanggalnya benar dan nadanya sopan, bukan menuntut."},
{n:21,type:"classify",micro:"Pesan jelas vs membingungkan",q:"Kelompokkan tiap pesan ke 'Jelas' atau 'Membingungkan'.",items:["'Rapat OSIS dimajukan ke Kamis jam 3 di ruang 12.'","'eh jadi gimana yang kemarin itu'","'Tolong bawa 2 spidol hitam besok ya.'","'nanti aja deh yang itu'"],groups:["Jelas","Membingungkan"],answer:{"Jelas":["'Rapat OSIS dimajukan ke Kamis jam 3 di ruang 12.'","'Tolong bawa 2 spidol hitam besok ya.'"],"Membingungkan":["'eh jadi gimana yang kemarin itu'","'nanti aja deh yang itu'"]},explain:"Jelas: menyebut apa, kapan, di mana, berapa. Membingungkan: 'yang itu', 'yang kemarin', 'nanti' tanpa acuan.",hint:"Bisa langsung dipahami & ditindaklanjuti, atau perlu bertanya lagi?"},
{n:22,type:"mcq",micro:"Struktur pesan panjang",q:"Untuk menyampaikan beberapa hal dalam satu pesan, cara agar mudah dibaca:",options:["Acak tanpa urutan, supaya pembaca memilih sendiri yang dianggap penting","Pakai poin bernomor atau baris terpisah, satu hal per baris","Satu paragraf panjang tanpa jeda, supaya terlihat lengkap dan rapat"],answer:1,explain:"Di layar, poin bernomor jauh lebih mudah dipindai daripada paragraf padat. Pembaca bisa menjawab per poin.",hint:"Poin bernomor, atau paragraf padat?"},
{n:23,type:"mcq",micro:"Nada: menambahkan kelembutan",q:"'Kerjakan sekarang.' bisa terbaca kasar di teks. Versi yang lebih baik tanpa kehilangan kejelasan:",options:["'KERJAKAN SEKARANG!!! Tenggatnya sore ini, jangan lelet!'","'kerjain napa, udah mepet tuh, lelet banget sih kalian'","'Tolong dikerjakan sekarang ya, soalnya tenggatnya sore ini.'"],answer:2,explain:"'Tolong' + alasan singkat + 'ya' mengubah perintah dingin menjadi permintaan yang wajar.",hint:"Tolong + alasan + 'ya', atau kapital / kasar?"},
{n:24,type:"mcq",micro:"Menghindari makna ganda",q:"Pesan 'Aku nggak bisa datang besok pagi, sore aja' — kalau ambigu 'sore aja' itu tawaran atau keputusan, sebaiknya...",options:["Perjelas: 'Aku nggak bisa besok pagi. Bisa nggak kalau kita ketemu besok sore jam 4?'","Biarkan, mereka akan mengerti sendiri maksud kita dari konteks kejadian sebelumnya","Kirim lebih cepat lagi supaya mereka tak sempat membuat rencana lain di hari yang sama"],answer:0,explain:"Kalimat yang bisa dua tafsir perlu ditulis ulang agar hanya satu tafsir yang mungkin.",hint:"Tulis ulang untuk satu makna, atau biarkan ambigu?"},
{n:25,type:"mcq",micro:"Pesan emosional: tunggu dulu",q:"Kamu marah & ingin mengirim pesan panjang penuh kemarahan. Sikap bijak:",options:["Kirim dulu pesannya, lalu hapus cepat-cepat, kemudian kirim lagi dengan kata-kata yang sedikit lebih halus supaya terasa adil","Tulis dulu kalau perlu, tapi jangan langsung kirim; baca ulang setelah tenang & sunting jadi pesan yang menyampaikan masalah tanpa menyerang","Kirim segera selagi masih panas supaya terdengar jujur dan perasaanmu tersampaikan apa adanya tanpa disaring atau dipikirkan dampaknya"],answer:1,explain:"Pesan yang dikirim saat marah sulit ditarik & sering memperburuk keadaan. Jeda + sunting menyelamatkan hubungan.",hint:"Tunda & sunting, atau kirim selagi panas?"},
{n:26,type:"mcq",micro:"Konfirmasi pemahaman",q:"Setelah menerima instruksi tertulis yang penting, balasan yang baik:",options:["'Oke' saja (tanpa memastikan paham), supaya terlihat patuh dan cepat menanggapi pesan","(tidak membalas dan berharap orang lain akan mengingatkan bagianmu nanti kalau lupa)","'Oke, jadi aku kerjakan bagian A & B, kumpul Jumat siang, betul?' — mengulang untuk memastikan"],answer:2,explain:"Mengulang instruksi dengan kata-katamu sendiri mengecek pemahaman & memberi pengirim kesempatan meluruskan.",hint:"Ulang untuk konfirmasi, atau 'oke' saja / diam?"},
{n:27,type:"tf",micro:"Membalas cepat itu wajib?",q:"Benar atau Salah: Kamu wajib membalas setiap pesan dalam hitungan menit, dan tidak melakukannya berarti kamu tidak sopan.",answer:false,explain:"Sebaliknya, wajar untuk membalas ketika kamu sempat, terutama untuk pesan yang butuh pemikiran. Yang penting adalah membalas dalam waktu yang wajar, bukan seketika.",hint:"Wajib balas dalam menit, atau dalam waktu yang wajar?"},
{n:28,type:"tf",micro:"Baca sebelum balas",q:"Benar atau Salah: Membaca seluruh pesan (atau seluruh utas percakapan) sampai selesai sebelum membalas mencegah kamu menjawab hal yang sebenarnya sudah dijelaskan.",answer:true,explain:"Membalas potongan pesan tanpa membaca utuh adalah penyebab umum salah paham & jawaban yang tidak nyambung.",hint:"Baca utuh dulu, atau balas potongan?"},
{n:29,type:"mcq",micro:"Pesan susulan yang mengganggu",q:"Setelah mengirim pertanyaan, mengirim '?' setiap beberapa menit membuat penerima...",options:["Merasa didesak & terganggu; lebih baik satu pengingat sopan setelah waktu yang wajar","Merasa dihargai karena kamu tampak sangat peduli pada urusannya dan pekerjaannya","Membalas lebih cepat dan senang karena diingatkan berkali-kali oleh banyak pesan"],answer:0,explain:"Spam pengingat menandakan kamu tidak menghormati waktu orang. Sabar + satu pengingat sopan sudah cukup.",hint:"Satu pengingat sopan, atau spam '?'?"},
{n:30,type:"order",micro:"Menulis email ke pihak yang belum dikenal",q:"Urutkan bagian email/pesan formal ke panitia lomba yang belum kamu kenal.",items:["Judul/baris pertama yang menjelaskan isi: 'Pertanyaan soal syarat pendaftaran Lomba X'","Sapaan + perkenalan singkat: 'Selamat pagi, saya ... dari sekolah ...'","Isi: pertanyaan/permintaan yang jelas & spesifik","Penutup: terima kasih + nama + kontak"],answer:[0,1,2,3],explain:"Judul informatif → sapaan & perkenalan → isi spesifik → penutup dengan identitas. Format ini menghormati pembaca.",hint:"Apa yang pembaca lihat pertama sebelum membuka pesan?"},
{n:31,type:"mcq",micro:"Nada pasif-agresif di teks",q:"Balasan 'Ya udah kalau gitu 🙂' setelah ketidaksepakatan sering terbaca...",options:["Netral sepenuhnya karena tidak menyatakan pendapat maupun perasaan kepada anggota lain dan menghindari konflik","Pasif-agresif — seolah setuju tapi sebenarnya kesal; lebih baik jujur: 'Aku masih kurang sreg, tapi ayo kita coba dulu'","Sangat ramah dan tulus, sehingga anggota lain merasa nyaman dan semua masalah tersembunyi ikut hilang sendiri"],answer:1,explain:"Emoji senyum di atas kekesalan membuat penerima bingung. Kejujuran yang sopan lebih baik daripada senyum menyindir.",hint:"Pasif-agresif, atau tulus?"},
{n:32,type:"tf",micro:"Sesuaikan gaya dengan penerima",q:"Benar atau Salah: Gaya menulis yang pas untuk chat ke sahabat (singkatan, tanpa sapaan, banyak emoji) sama-sama pas dipakai untuk pesan ke guru atau panitia.",answer:false,explain:"Sebaliknya, menyesuaikan tingkat formalitas dengan penerima & konteks adalah bagian dari komunikasi tertulis yang baik. Terlalu santai ke pihak yang mengharapkan formalitas bisa terbaca kurang menghormati.",hint:"Satu gaya untuk semua, atau menyesuaikan penerima?"},
{n:33,type:"mcq",micro:"Menyampaikan kabar buruk tertulis",q:"Menyampaikan kabar kurang menyenangkan lewat teks (mis. membatalkan janji):",options:["Kirim di menit terakhir tanpa penjelasan, supaya tak ada waktu bagi orang itu untuk protes","Hilang begitu saja tanpa kabar dan tak membalas pesan, supaya tak perlu menjelaskan alasan","Sampaikan langsung & jelas + minta maaf + alasan singkat + tawaran alternatif bila ada"],answer:2,explain:"Kabar buruk tetap perlu jelas & sopan. Memberi tahu lebih awal + minta maaf + alternatif menunjukkan menghargai orang.",hint:"Jelas + maaf + alternatif lebih awal, atau menit terakhir / hilang?"},
{n:34,type:"mcq",micro:"Menghindari kesan menuntut",q:"Meminta bantuan lewat teks tanpa terkesan menuntut:",options:["'Kalau kamu ada waktu, boleh bantu cek bagian ini? Nggak buru-buru kok.'","'Cek ini.' (satu kalimat perintah singkat tanpa sapaan, tanpa tolong, dan tanpa penjelasan)","'Kenapa sih kamu belum bantu dari tadi? Kamu nggak lihat aku kerepotan banget?'"],answer:0,explain:"Mengakui bahwa orang punya kesibukan & memberi ruang untuk menolak membuat permintaan terasa hormat.",hint:"Beri ruang & konteks, atau memerintah?"},
{n:35,type:"mcq",micro:"Memindai vs membaca",q:"Karena orang cenderung memindai pesan di layar, tulisan yang baik...",options:["Menulis semuanya dalam satu kalimat panjang tanpa titik atau koma supaya terlihat padat","Menaruh info terpenting di depan, memakai baris pendek, & menandai poin penting","Menyembunyikan info terpenting di tengah paragraf panjang, supaya pembaca membaca sampai habis"],answer:1,explain:"Tulis untuk pembaca yang buru-buru: mereka harus bisa menangkap inti meski hanya memindai.",hint:"Info penting di depan & mudah dipindai, atau terkubur?"},
{n:36,type:"mcq",micro:"Balasan yang menutup, bukan menggantung",q:"Setelah diskusi teks selesai & rencana disepakati, menutup dengan...",options:["(berhenti membalas tiba-tiba dan membiarkan lawan bicara menebak kesepakatannya)","'Hmm' lalu diam, supaya lawan bicara yang menyimpulkan sendiri hasil kesepakatan itu","'Oke sip. Jadi: kita ketemu Sabtu jam 9 di gerbang. Sampai ketemu!' — merangkum kesepakatan"],answer:2,explain:"Rangkuman kesepakatan di akhir memastikan kedua pihak punya pemahaman yang sama & percakapan terasa tuntas.",hint:"Rangkum kesepakatan, atau berhenti tiba-tiba?"},
{n:37,type:"tf",micro:"Sarkasme di teks berisiko",q:"Benar atau Salah: Sarkasme (mengatakan kebalikan dari maksudmu untuk efek) berisiko tinggi di teks karena pembaca tidak mendengar nada & bisa menganggapnya serius.",answer:true,explain:"'Wah, ide brilian banget' tanpa nada bisa terbaca sebagai pujian tulus atau ejekan. Di teks, lebih aman berkata langsung.",hint:"Sarkasme di teks aman, atau mudah salah tangkap?"},
{n:38,type:"mcq",micro:"Menandai penerima di grup",q:"Di grup, kalau pesanmu ditujukan untuk orang tertentu:",options:["Sebut namanya di awal ('@Rani, tolong...') supaya jelas siapa yang perlu bertindak","Tulis tanpa menyebut nama dan berharap orang yang dimaksud sadar sendiri bahwa itu untuknya","Kirim sebagai pesan pribadi yang terpisah satu per satu, bukan di grup, supaya tak terlewat"],answer:0,explain:"Menyebut penerima menghilangkan kebingungan 'ini buat siapa ya?' & 'diffusion of responsibility' di grup.",hint:"Sebut nama, atau berharap sadar sendiri?"},
{n:39,type:"mcq",micro:"Pesan tanpa konteks",q:"Mengirim 'gagal' atau 'nggak bisa' tanpa penjelasan membuat penerima...",options:["Merasa dihargai karena sistem sudah memberi tahu bahwa ia gagal","Bingung: apa yang gagal? kenapa? apa yang harus dilakukan sekarang?","Langsung paham karena pesan error seperti itu sudah umum dan jelas"],answer:1,explain:"Selalu beri konteks secukupnya: 'Pendaftaran gagal karena kuota penuh. Kita coba jalur lain besok?'",hint:"Beri konteks, atau satu kata tanpa penjelasan?"},
{n:40,type:"open",micro:"Menyunting pesan buruk",q:"Sunting pesan ini menjadi versi yang jelas & sopan, lalu jelaskan perbaikannya: 'p... eh besok jd ga? gua udh siapin semua loh capek tau ga klo batal lg mending lo bilang skrg'",explain:"Jawaban baik menghasilkan pesan yang: menyapa + menyebut tujuan, meminta kepastian dengan jelas, menyampaikan fakta (sudah menyiapkan) tanpa menyalahkan/mengeluh, kalimat lengkap + tanda baca, penutup sopan — lalu menjelaskan perbaikannya (buang pembuka kosong, ubah nada menyalahkan jadi permintaan tenang, perjelas, tambah penutup).",hint:"Buang 'p'; ubah keluhan/tuduhan jadi permintaan tenang dengan alasan; kalimat lengkap; tutup sopan.",sample:"Versi yang disunting: 'Hai. Aku mau pastikan soal acara besok — jadi atau tidak? Aku sudah menyiapkan semua perlengkapan, jadi kalau ada kemungkinan batal, tolong kabari aku sekarang ya biar aku bisa menyesuaikan. Makasih.' Perbaikan: (1) Membuang pembuka kosong 'p' dan langsung menyapa + menyebut tujuan pesan. (2) Mengubah nada yang menyalahkan dan mengeluh ('capek tau ga', 'mending lo bilang') menjadi permintaan yang tenang: menyebut fakta (sudah menyiapkan semua) tanpa menuduh, lalu meminta kepastian lebih awal dengan alasan yang jelas. (3) Memakai kalimat lengkap dan tanda baca supaya mudah dibaca. (4) Menutup dengan 'makasih' supaya tidak terdengar menuntut. Isi intinya sama (minta kepastian, sebut sudah repot menyiapkan), tapi cara penyampaiannya tidak menyerang sehingga penerima lebih mungkin merespons dengan baik."},
{n:41,type:"mcq",micro:"Skenario: minta tolong ke kakak kelas via chat",q:"Kamu ingin minta tips dari kakak kelas lewat DM. Pesan yang menghargai waktunya:",options:["'kak ajarin desain dong dari 0 sampai bisa, aku butuh sekarang soalnya mau lomba minggu depan, bales ya kak cepetan, jangan lama-lama'","'kak' lalu menunggu dibalas dulu baru menjelaskan keperluan, karena pesan pendek dianggap lebih sopan dan tak mengganggu kakak itu yang sedang sibuk","'Halo Kak. Aku [nama] kelas 8. Aku lagi belajar desain grafis dan lihat karya Kakak keren. Boleh tanya, tools apa yang Kakak rekomendasiin buat pemula?'"],answer:2,explain:"Sapaan + perkenalan + konteks + pertanyaan spesifik = mudah dijawab & menunjukkan kamu serius.",hint:"Konteks + pertanyaan spesifik, atau 'ajarin dari 0'?"},
{n:42,type:"mcq",micro:"Skenario: koordinasi tugas kelompok di chat",q:"Cara mengoordinasi pembagian tugas kelompok lewat chat agar tidak kacau:",options:["Kirim satu pesan berisi daftar: nama - bagian - tenggat, lalu minta tiap orang konfirmasi 'oke'","Bahas sepotong-sepotong di banyak waktu berbeda tanpa merangkum hasilnya, supaya semua sempat ikut","Anggap semua paham tanpa menuliskannya, karena pembagian tugas sudah dibicarakan sekilas saat belajar"],answer:0,explain:"Pembagian tertulis + konfirmasi tiap orang mencegah 'kukira kamu yang kerjakan' di kemudian hari.",hint:"Daftar tertulis + konfirmasi, atau sepotong-sepotong?"},
{n:43,type:"mcq",micro:"Skenario: salah kirim pesan",q:"Kamu tidak sengaja mengirim pesan ke grup yang salah / orang yang salah. Sikap:",options:["Menyalahkan aplikasinya panjang lebar di grup, mengeluh bahwa tampilannya membingungkan dan tombolnya berdekatan","Segera akui & minta maaf singkat bila perlu: 'Maaf, pesan tadi salah kirim ya'; hapus bila fiturnya ada","Pura-pura tidak terjadi apa-apa dan berharap tak ada yang melihat pesan itu, lalu diam saja sampai grupnya sepi"],answer:1,explain:"Mengakui kesalahan kecil dengan tenang jauh lebih baik daripada diam canggung atau drama.",hint:"Akui + minta maaf singkat, atau pura-pura / menyalahkan aplikasi?"},
{n:44,type:"mcq",micro:"Skenario: menanggapi pesan yang menyakiti",q:"Seseorang mengirim pesan yang menyakiti hatimu. Sebelum membalas:",options:["Membalas segera dengan kata-kata yang lebih menyakitkan lagi, supaya ia tahu bagaimana rasanya disakiti seperti itu","Mengambil screenshot lalu menyebarkannya ke banyak orang supaya mereka ikut menilai betapa jahatnya pesan itu kepadamu","Beri jeda, jangan balas selagi terluka; setelah tenang, tanggapi isinya dengan tenang atau bicarakan langsung"],answer:2,explain:"Balasan saat terluka biasanya memperburuk. Jeda + tanggapan tenang (atau bicara langsung) lebih menyelesaikan.",hint:"Jeda + tanggapan tenang, atau balas menyakiti / sebarkan?"},
{n:45,type:"order",micro:"Menulis pesan meminta maaf",q:"Urutkan bagian pesan permintaan maaf yang tulus (tertulis).",items:["Sebut secara spesifik apa yang kamu sesali: 'Maaf ya aku telat bales & bikin kamu nunggu lama'","Akui dampaknya tanpa alasan berlebihan: 'Itu pasti bikin kamu kesel'","Sebut apa yang akan kamu lakukan berbeda","Beri ruang buat responsnya, jangan menuntut dimaafkan"],answer:[0,1,2,3],explain:"Sebut kesalahan spesifik → akui dampak → niat perbaikan → beri ruang. Bukan 'maaf ya kalau kamu tersinggung'.",hint:"Apa yang disebut pertama dalam permintaan maaf yang tulus?"},
{n:46,type:"mcq",micro:"Skenario: menjawab pertanyaan panjang",q:"Temanmu mengirim pesan berisi 4 pertanyaan sekaligus. Cara menjawab agar jelas:",options:["Jawab per nomor / kutip tiap pertanyaan lalu jawab di bawahnya","Menjawab satu pertanyaan yang paling mudah dan mengabaikan tiga lainnya","Menjawab semuanya digabung dalam satu kalimat panjang tanpa pemisah"],answer:0,explain:"Struktur per poin memastikan tidak ada pertanyaan yang terlewat & mudah dibaca.",hint:"Jawab per poin, atau satu kalimat gabungan?"},
{n:47,type:"mcq",micro:"Skenario: pesan ke guru di luar jam sekolah",q:"Kamu perlu mengirim pesan ke guru jam 9 malam untuk hal yang tidak mendesak. Sikap yang menghormati:",options:["Menelepon berkali-kali sampai diangkat, karena ingin urusan cepat selesai walau sudah lewat jam sembilan malam dan guru tampak sibuk","Tulis pesannya sekarang tapi jadwalkan/kirim besok pagi; atau kirim dengan pembuka 'Mohon maaf mengganggu di luar jam, ini tidak mendesak, bisa dibalas besok'","Mengirim pesan lalu mengharapkan balasan malam itu juga, & merasa kesal bila guru belum menjawab dalam waktu satu jam setelah pesanmu terkirim"],answer:1,explain:"Menghormati waktu istirahat orang. Untuk hal tidak mendesak, kirim di jam yang wajar atau beri catatan.",hint:"Tunda ke pagi / beri catatan, atau harap balasan malam itu?"},
{n:48,type:"mcq",micro:"Skenario: menyampaikan ketidaksetujuan di grup",q:"Kamu tidak setuju keputusan grup yang sudah dibahas di chat. Cara menyampaikan:",options:["'Ini keputusan bodoh. Kenapa sih kalian memilih A? Jelas-jelas B jauh lebih masuk akal untuk kita semua!'","Diam saja di grup, tetapi mengeluh kepada teman-teman satu per satu lewat pesan pribadi tentang keputusan yang sudah dibuat","'Aku ngerti mayoritas milih A. Cuma aku masih khawatir soal biayanya — boleh kita bahas ini sebentar sebelum final?'"],answer:2,explain:"Akui posisi grup + sampaikan kekhawatiran spesifik + minta ruang bahas. Bukan menyerang atau menggosip di belakang.",hint:"Akui + kekhawatiran spesifik + minta bahas, atau menyerang / gosip?"},
{n:49,type:"mcq",micro:"Skenario: mengirim tugas/lampiran",q:"Mengirim file tugas ke guru, hal yang membuatnya rapi & mudah:",options:["Beri nama file yang jelas ('TugasIPA_Dina_8A.pdf'), sertakan pesan singkat menjelaskan isinya, pastikan file benar terkirim","Kirim file bernama 'Untitled(3).docx' tanpa pesan, karena guru tahu itu tugas dari siapa dan untuk pelajaran apa kelas","Kirim 5 file terpisah satu per satu tanpa keterangan, supaya guru memilih sendiri file yang paling lengkap di antaranya"],answer:0,explain:"Nama file yang jelas + pesan pengantar menghemat waktu penerima & menunjukkan kerapian.",hint:"Nama jelas + pesan pengantar, atau 'Untitled' tanpa keterangan?"},
{n:50,type:"open",micro:"Menulis pesan koordinasi",q:"Kamu ketua kelompok. Anggota: Rio, Sinta, Bagas. Tugas: bikin poster (riset, desain, penulisan teks). Tenggat Jumat. Tulis SATU pesan grup yang mengoordinasi ini dengan jelas, lalu jelaskan mengapa formatnya begitu.",explain:"Jawaban baik menghasilkan satu pesan yang: menyebut tenggat besar di awal, memakai poin bernomor (nama - bagian - sub-tenggat), menyusun tenggat bertahap sesuai ketergantungan tugas, meminta konfirmasi tiap anggota, meminta kabar dini bila ada kendala, dan bernada ramah — lalu menjelaskan alasan tiap elemen format.",hint:"Tenggat di awal, poin bernomor nama-bagian-subtenggat, tahapan sesuai ketergantungan, minta konfirmasi, nada ramah.",sample:"Pesan grup: 'Halo tim! Ini pembagian tugas poster kita, tenggat Jumat 6 September jam 8 malam: 1) Riset & kumpulkan data + sumber — Rio (selesai Rabu supaya bisa dipakai yang lain). 2) Desain layout & visual poster — Sinta (mulai Rabu setelah data masuk, draf Kamis). 3) Penulisan teks poster (judul, poin isi, ajakan) — Bagas (draf Kamis). 4) Aku gabungkan & rapikan Jumat siang, lalu kita cek bareng jam 4. Tolong masing-masing balas 'oke' kalau setuju, atau bilang kalau ada kendala. Kalau bagian kalian mepet, kabari aku secepatnya ya, jangan pas hari-H. Makasih semua!' Kenapa formatnya begitu: (1) Sebut tenggat besar di awal supaya semua sadar batas waktu. (2) Poin bernomor: nama - bagian - sub-tenggat, jadi tiap orang tahu persis tugas dan kapan. (3) Tenggat bertahap (Rabu, Kamis, Jumat) supaya pekerjaan tidak menumpuk di akhir dan bagian yang saling bergantung punya urutan. (4) Minta konfirmasi 'oke' dari tiap orang supaya ada kesepakatan, bukan asumsi. (5) Minta kabar dini kalau ada kendala. (6) Nada ramah ('Halo tim', 'makasih') supaya tidak terasa memerintah."},
{n:51,type:"mcq",micro:"Skenario: pesan yang belum selesai kepikiran",q:"Kamu mulai mengetik pesan penting lalu ragu. Sebaiknya:",options:["Kirim apa adanya meski maksudmu belum jelas, lalu perbaiki lewat pesan susulan kalau penerima bingung","Simpan sebagai draf, pikirkan dulu apa tujuanmu & apa yang ingin dicapai, baru selesaikan & kirim","Kirim setengah jadi sekarang juga, lalu lanjutkan menulis sisanya lewat pesan berikutnya selagi ide terlintas"],answer:1,explain:"Pesan penting layak dipikirkan. Draf yang matang lebih baik daripada rentetan pesan setengah jadi yang membingungkan.",hint:"Matangkan dulu, atau kirim setengah jadi?"},
{n:52,type:"tf",micro:"Screenshot & konteks",q:"Benar atau Salah: Membagikan screenshot percakapan pribadi seseorang ke orang lain tanpa izin tidak masalah selama isi pesannya benar.",answer:false,explain:"Sebaliknya, itu bisa melanggar kepercayaan & menyebarkan pesan yang lepas dari konteksnya sehingga mudah disalahpahami. Orang berhak atas privasi percakapannya.",hint:"Sebar screenshot pribadi tanpa izin = aman, atau melanggar kepercayaan?"},
{n:53,type:"mcq",micro:"Skenario: menjelaskan langkah lewat teks",q:"Menjelaskan cara melakukan sesuatu (mis. mengisi formulir online) lewat teks:",options:["Tulis dalam satu paragraf panjang tanpa urutan jelas, supaya pembaca membaca sampai habis sebelum mencoba","'Gampang kok, coba aja sendiri nanti juga ketemu, tombolnya ada di mana-mana, tinggal diklik saja.'","Tulis langkah bernomor, sebutkan tampilan yang akan dilihat di tiap langkah, & tawarkan bantuan bila macet"],answer:2,explain:"Tanpa bisa menunjuk layar, instruksi tertulis harus sangat runtut & menyebut penanda visual.",hint:"Langkah bernomor + penanda visual, atau paragraf / 'coba sendiri'?"},
{n:54,type:"mcq",micro:"Skenario: menerima info yang meragukan via chat",q:"Kamu menerima pesan berantai berisi kabar mengejutkan & diminta menyebarkannya. Sikap:",options:["Jangan langsung sebarkan; cek kebenarannya dari sumber tepercaya dulu; kalau ternyata hoaks, beri tahu pengirimnya dengan sopan","Sebarkan segera ke kontak yang kamu punya, karena kabar mengejutkan harus cepat diketahui banyak orang, terutama di grup keluarga","Percaya penuh karena dikirim oleh temanmu sendiri, & teman tidak mungkin menyebarkan kabar yang tidak benar kepadamu"],answer:0,explain:"Menyebarkan kabar tanpa memeriksa membuatmu ikut menyebarkan hoaks. Verifikasi dulu, sebar kemudian (atau tidak sama sekali).",hint:"Cek dulu, atau sebar segera?"},
{n:55,type:"mcq",micro:"Skenario: kata-kata yang tak bisa ditarik",q:"Kamu mengirim pesan kasar saat kesal, lalu menyesal. Langkah pemulihan:",options:["Menyalahkan orang itu karena ia 'sudah memancing' kemarahanmu lebih dulu, sehingga tak perlu meminta maaf, lalu lanjut seperti biasa di grup","Minta maaf dengan tulus & spesifik ('Maaf tadi aku ngomongnya kasar, itu nggak pantas'), akui, & sampaikan ulang kekesalan dengan cara lebih baik bila perlu","Menghapus pesan kasar itu lalu berharap teman-teman melupakannya begitu saja tanpa meminta maaf, menjelaskan, atau menyinggungnya lagi nanti"],answer:1,explain:"Teks yang kasar meninggalkan jejak & luka. Permintaan maaf yang tulus + memperbaiki cara adalah tanggung jawabmu.",hint:"Minta maaf tulus + perbaiki cara, atau hapus diam-diam / menyalahkan?"},
{n:56,type:"mcq",micro:"Skenario: pesan panjang yang dibalas 'ok'",q:"Kamu mengirim penjelasan panjang & penting, dibalas 'ok' saja. Sikap yang tidak buru-buru tersinggung:",options:["Langsung menyimpulkan bahwa dia tidak peduli pada penjelasanmu & sedang marah, lalu membalas dengan nada ketus pula","Membalas dengan 'ok' yang lebih dingin lagi tanpa tanda baca, supaya dia tahu bagaimana rasanya diperlakukan seperti itu","Ingat teks kehilangan nada; 'ok' mungkin cuma singkat. Kalau perlu memastikan, tanya: 'Oke berarti kamu setuju sama rencananya ya?'"],answer:2,explain:"Mengisi 'nada yang hilang' dengan tafsir terburuk adalah sumber banyak konflik chat. Konfirmasi sebelum bereaksi.",hint:"Konfirmasi dulu, atau tersinggung & membalas dingin?"},
{n:57,type:"tf",micro:"Menulis membantu berpikir",q:"Benar atau Salah: Menuliskan sesuatu (bahkan yang tidak akan dikirim) sering membantu kamu memperjelas pikiranmu sendiri tentang suatu masalah.",answer:true,explain:"Menyusun kalimat memaksa kamu mengurutkan gagasan. Banyak orang menulis draf untuk berpikir, bukan hanya untuk berkomunikasi.",hint:"Menulis membantu berpikir, atau hanya untuk komunikasi?"},
{n:58,type:"mcq",micro:"Skenario: menanggapi banyak pesan menumpuk",q:"Setelah offline seharian, ada 30 pesan di berbagai chat. Cara mengelola:",options:["Balas yang mendesak/penting dulu; untuk yang butuh waktu, kirim 'aku baca, nanti aku jawab'; tidak semua harus dijawab panjang","Abaikan semuanya sampai kamu punya waktu luang, lalu balas sekaligus dalam satu pesan panjang, walau sudah terlambat","Balas semua asal cepat tanpa membaca isinya, supaya terlihat sigap dan tidak membuat pengirim menunggu lama"],answer:0,explain:"Prioritaskan. Mengakui pesan + menjadwalkan jawaban lebih baik daripada mengabaikan atau membalas sembarangan.",hint:"Prioritaskan + akui yang butuh waktu, atau abaikan / balas asal?"},
{n:59,type:"mcq",micro:"Skenario: bercanda lewat teks ke orang baru",q:"Bercanda dengan teman baru lewat chat, agar tidak salah terima:",options:["Tidak bercanda dengan teman baru, bahkan setelah bertahun-tahun berteman dan sudah saling mengenal baik satu sama lain","Awalnya lebih hati-hati; pakai penanda ('becanda ya 😄') untuk humor yang bisa salah tangkap sampai kalian saling kenal gayanya","Lempar candaan sarkastik yang tajam sejak awal perkenalan supaya terlihat lucu dan cepat akrab dengan teman baru itu"],answer:1,explain:"Sebelum saling paham 'nada' masing-masing, humor tekstual berisiko. Penanda & kehati-hatian membantu.",hint:"Hati-hati + penanda dulu, atau sarkas tajam sejak awal?"},
{n:60,type:"open",micro:"Skenario menyeluruh: kesalahpahaman chat",q:"Kamu dan sahabatmu bertengkar gara-gara chat: kamu menulis 'ya udah lah terserah' saat lelah, dia menganggapmu marah dan tidak peduli, lalu membalas dingin, dan sekarang kalian saling diam. Rancang bagaimana kamu memakai komunikasi tertulis (atau memilih tidak) untuk memperbaikinya.",explain:"Jawaban baik: mengidentifikasi akar masalah (nada hilang di teks), memilih media yang tepat (untuk konflik emosional, lebih baik bicara langsung/telepon; teks sebagai cadangan), menyusun pesan pemulihan yang mengakui dampak + menjelaskan maksud tanpa menyalahkan + menegaskan menghargai hubungan, membaca ulang untuk nada, memberi ruang respons, dan menarik pelajaran untuk mencegah pengulangan.",hint:"Kenali 'nada hilang'; pilih bicara langsung untuk konflik emosional; kalau teks: akui dampak + jelaskan maksud tanpa menyalahkan + baca ulang; beri ruang; ambil pelajaran.",sample:"(1) Aku sadari akar masalahnya adalah nada yang hilang: kalimat 'ya udah lah terserah' yang kumaksud sebagai 'aku capek, ikut kamu aja' terbaca sebagai 'aku marah dan nggak peduli'. (2) Untuk hal yang sudah jadi konflik emosional seperti ini, teks berisiko memperkeruh, jadi kalau memungkinkan aku ajak bicara langsung atau telepon: 'Hei, soal chat kemarin, bisa kita ngobrol bentar? Aku ngerasa ada salah paham.' (3) Kalau harus lewat teks, aku tulis pesan yang: mengakui dampaknya (mis. 'Aku baca lagi chat kemarin, dan aku ngerti kenapa kalimatku itu kedengeran kayak aku marah dan cuek. Maaf ya.'), menjelaskan maksud sebenarnya tanpa menyalahkan dia (mis. 'Waktu itu aku capek banget dan maksudku sebenarnya aku ikut kamu aja, bukan ngambek.'), dan menyampaikan bahwa aku menghargai dia (mis. 'Aku nggak mau salah paham gini bikin kita saling diam.'). (4) Aku baca ulang pesan itu sebelum kirim untuk memastikan nadanya tulus, bukan defensif. (5) Aku beri dia ruang untuk merespons dan tidak menuntut langsung baikan. (6) Pelajaran untuk ke depan: kalau aku sedang lelah dan berpotensi mengirim pesan yang bisa disalahartikan, lebih baik aku bilang 'aku lagi capek, kita lanjut besok ya' daripada mengirim kalimat pendek yang ambigu."},
{n:61,type:"mcq",micro:"Mengapa teks mudah salah paham",q:"Alasan mendasar pesan tertulis lebih rentan disalahtafsir daripada percakapan langsung:",options:["Karena orang pada dasarnya tidak bisa membaca dengan benar, sehingga mereka salah paham pada hal tertulis sejak dahulu","Karena tulisan lebih rumit daripada ucapan, sehingga isinya jauh lebih sulit dipahami daripada percakapan langsung dengan teman","Hilangnya nada suara, ekspresi wajah, & kemampuan langsung bertanya 'maksudmu apa?' — pembaca mengisi celah itu dengan tafsirnya sendiri"],answer:2,explain:"Dalam percakapan, salah paham langsung ketahuan & diperbaiki. Di teks, ia bisa membeku & membesar.",hint:"Sinyal & klarifikasi langsung hilang, atau orang tak bisa membaca?"},
{n:62,type:"mcq",micro:"Permanen & bisa diteruskan",q:"Perbedaan penting pesan digital dari ucapan lisan:",options:["Pesan digital bisa disimpan, di-screenshot, diteruskan, & muncul lagi bertahun-tahun kemudian — jadi pikirkan sebelum menulis hal sensitif","Pesan digital terhapus otomatis setelah beberapa hari, jadi tidak perlu terlalu hati-hati menulis hal sensitif di grup","Tidak ada bedanya antara pesan digital dan ucapan langsung, karena keduanya sama-sama cepat dilupakan orang yang menerimanya"],answer:0,explain:"'Tulis seolah pesanmu bisa dibaca orang yang tidak kamu tuju.' Ucapan menguap; teks bertahan.",hint:"Bisa disimpan & disebar, atau menguap seperti ucapan?"},
{n:63,type:"tf",micro:"Jeda sebelum kirim itu berharga",q:"Benar atau Salah: Memberi jeda beberapa menit (atau lebih) sebelum mengirim pesan yang ditulis saat emosi tinggi sering mencegah kerusakan hubungan yang sulit diperbaiki.",answer:true,explain:"Pesan emosional yang terkirim tidak bisa ditarik & sering memicu balasan yang setara. Jeda + sunting adalah rem penting.",hint:"Jeda sebelum kirim = berharga, atau tak berpengaruh?"},
{n:64,type:"mcq",micro:"Menilai kejelasan tulisanmu",q:"Cara menguji apakah pesanmu jelas sebelum mengirim:",options:["Kirim dulu lalu lihat apakah penerimanya bingung; kalau bingung, baru jelaskan ulang dengan kata lain","Bayangkan kamu si penerima yang sibuk & tidak tahu konteksnya: apakah kamu akan langsung paham apa yang diminta?","Anggap pesanmu jelas karena kamu sendiri yang menulis dan sudah mengerti maksudmu sepenuhnya, jadi tak perlu dicek"],answer:1,explain:"Kamu tahu maksudmu, jadi tulisanmu terasa jelas bagimu. Menguji dari sudut pembaca menangkap celah.",hint:"Uji dari sudut pembaca, atau anggap jelas?"},
{n:65,type:"mcq",micro:"Formalitas sebagai bentuk hormat",q:"Mengapa menyesuaikan tingkat formalitas dengan penerima itu penting?",options:["Formalitas tidak penting dalam komunikasi tertulis, karena yang terpenting hanya isi pesan, bukan siapa penerimanya","Gunakan bahasa paling formal untuk semua jenis penerima, termasuk sahabat dekat, supaya tak ada yang tersinggung","Terlalu santai ke orang yang mengharapkan formalitas bisa terbaca kurang menghormati; terlalu kaku ke teman terasa dingin"],answer:2,explain:"Sama seperti berpakaian sesuai acara, gaya tulisan menyesuaikan hubungan & konteks.",hint:"Menyesuaikan = menghormati, atau tidak penting?"},
{n:66,type:"tf",micro:"Balasan lambat = tidak peduli?",q:"Benar atau Salah: Kalau seseorang lambat membalas pesanmu, itu hampir selalu berarti mereka sengaja mengabaikanmu atau tidak peduli.",answer:false,explain:"Sebaliknya, ada banyak alasan tidak langsung membalas: sibuk, tidak sempat, ingin menjawab dengan baik, lupa. Menyimpulkan yang terburuk sering keliru & memicu konflik.",hint:"Lambat balas = pasti tidak peduli, atau bisa banyak sebab?"},
{n:67,type:"mcq",micro:"Menulis ringkas itu sulit",q:"Mengapa pesan yang ringkas & jelas sering lebih sulit ditulis daripada yang panjang?",options:["Meringkas menuntut kamu memutuskan mana yang benar-benar penting & menyusunnya rapi, bukan sekadar menuangkan semua","Karena kata-kata yang pendek jauh lebih sulit dieja & diketik dengan benar daripada kata-kata yang panjang dan umum","Pesan panjang lebih baik karena memuat semua hal, sehingga menulis ringkas justru lebih mudah dan tak perlu banyak berpikir"],answer:0,explain:"'Maaf suratku panjang, aku tidak punya waktu membuatnya pendek.' Ringkas = hasil pemikiran, bukan kemalasan.",hint:"Meringkas butuh memilih & menyusun, atau sekadar mengeja?"},
{n:68,type:"mcq",micro:"Nada default pembaca",q:"Kalau sebuah pesan bisa dibaca dengan nada netral ATAU nada kesal, pembaca yang sedang tidak enak hati cenderung...",options:["Tidak terpengaruh oleh suasana hatinya, karena pembaca membaca pesan dengan cara yang persis sama, dalam kondisi apa saja","Membacanya dengan nada kesal — jadi saat menulis, tambahkan penanda kehangatan bila ada risiko salah tafsir","Membaca dengan nada positif dan ramah, karena orang cenderung mengira pesan berisi niat baik pengirim"],answer:1,explain:"Pembaca membawa suasana hatinya ke tiap pesan. Kata 'tolong', 'ya', atau emoji ramah menurunkan risiko salah baca.",hint:"Suasana hati pembaca memengaruhi tafsir, atau tidak?"},
{n:69,type:"mcq",micro:"Kapan lebih baik tidak menulis",q:"Untuk hal yang sangat sensitif, emosional, atau kompleks, sering lebih baik...",options:["Selalu lewat teks saja agar ada bukti tertulis yang bisa dipakai bila terjadi perselisihan di kemudian hari nanti","Tidak dibahas dengan siapa saja, karena hal sensitif sebaiknya dilupakan daripada menimbulkan salah paham, apalagi lewat teks","Bicara langsung atau telepon, karena nada & respons langsung membantu; teks bisa untuk menjadwalkan pembicaraan itu"],answer:2,explain:"Pilih media sesuai isi: teks bagus untuk info & koordinasi; percakapan langsung lebih baik untuk hal berat.",hint:"Bicara langsung untuk hal berat, atau selalu teks?"},
{n:70,type:"order",micro:"Menulis pesan sulit dengan tenang",q:"Urutkan proses menulis pesan yang isinya sulit (mis. menyampaikan kekecewaan).",items:["Tenangkan diri dulu; jangan menulis final saat emosi memuncak","Tentukan tujuan: apa yang aku ingin terjadi setelah pesan ini?","Tulis draf: sampaikan masalah pakai 'aku merasa', spesifik, tanpa serangan","Baca ulang dari sudut penerima, sunting nada, baru kirim"],answer:[0,1,2,3],explain:"Tenang → tujuan → draf 'aku' → baca ulang & sunting → kirim. Bukan menulis & mengirim dalam satu tarikan napas marah.",hint:"Apa yang harus tenang sebelum menulis?"},
{n:71,type:"mcq",micro:"Menulis untuk audiens yang beragam",q:"Kalau pesanmu di grup akan dibaca orang dengan latar & pemahaman berbeda:",options:["Pakai bahasa yang bisa diakses semua, jelaskan singkatan/istilah internal, & beri konteks secukupnya","Pakai semua singkatan dan istilah internal karena 'yang lama paham', sedangkan anggota baru belajar sendiri","Tulis serumit mungkin dengan banyak istilah teknis supaya pesanmu terlihat berbobot di mata anggota grup"],answer:0,explain:"Jargon & singkatan menyingkirkan anggota baru. Tulisan yang inklusif menerjemahkan untuk semua.",hint:"Bahasa yang bisa diakses semua, atau jargon internal?"},
{n:72,type:"tf",micro:"Kejelasan tulisan bisa dilatih",q:"Benar atau Salah: Kemampuan menulis pesan yang jelas & sopan adalah bakat tetap; kalau seseorang tidak memilikinya, latihan tidak akan banyak membantu.",answer:false,explain:"Sebaliknya, seperti keterampilan lain, menulis membaik dengan latihan, membaca ulang, & memperhatikan pesan orang yang tulisannya baik.",hint:"Bawaan, atau bisa dilatih?"},
{n:73,type:"mcq",micro:"Menilai apakah perlu membalas",q:"Tidak semua pesan butuh balasan panjang. Cara memutuskan:",options:["Jangan membalas apa-apa, karena diam adalah cara paling aman supaya tak ada salah paham atau pertengkaran baru, dan itu paling hemat waktu","Cek: apakah pengirim menunggu jawaban atau tindakan dariku? apakah diam akan menimbulkan salah paham? — kalau ya, balas (minimal akui)","Balas semuanya dengan panjang lebar tanpa kecuali, termasuk pesan yang hanya berisi stiker atau ucapan selamat pagi dari teman"],answer:1,explain:"Pesan yang jelas butuh respons (pertanyaan, permintaan, undangan) sebaiknya minimal diakui, agar pengirim tidak menggantung.",hint:"Cek apakah menunggu respons, atau balas semua / tak satu pun?"},
{n:74,type:"mcq",micro:"Efek 'terlihat online tapi tidak membalas'",q:"Kenapa 'dilihat tapi tidak dibalas' bisa terasa menyakitkan bagi pengirim?",options:["Tak ada efek, karena pengirim mengerti kamu sedang sibuk dan tak perlu diberi kabar, lagi pula ia akan memaklumi kesibukanmu","Karena pengirim terlalu sensitif & itu sepenuhnya bukan urusanmu, sehingga kamu tidak perlu memikirkan perasaannya sedikit pun","Terlihat seperti penolakan sadar; kalau kamu belum sempat menjawab, satu kalimat 'aku baca ya, nanti kubalas' sangat membantu"],answer:2,explain:"Pengakuan singkat menghilangkan kegalauan pengirim. Ini bagian dari komunikasi digital yang berempati.",hint:"Akui singkat kalau belum sempat, atau abaikan karena 'bukan urusanmu'?"},
{n:75,type:"tf",micro:"Tulisan mewakili dirimu",q:"Benar atau Salah: Cara seseorang menulis pesan — kejelasan, kesopanan, kerapian — ikut membentuk kesan orang lain tentang dirinya, terutama saat mereka belum bertemu langsung.",answer:true,explain:"Untuk pendaftaran, melamar kegiatan, atau menghubungi orang baru, pesanmu adalah 'kesan pertama'. Ia layak disiapkan.",hint:"Tulisan membentuk kesan, atau tak berpengaruh?"},
{n:76,type:"mcq",micro:"Menghindari perang komentar",q:"Di kolom komentar/grup, saat perdebatan mulai memanas & tidak produktif:",options:["Kamu boleh menyampaikan poinmu sekali dengan jelas & sopan, lalu memilih tidak melanjutkan; tidak semua debat harus 'dimenangkan'","Terus membalas setiap komentar sampai lawanmu menyerah & mengakui kesalahannya, karena debat harus dimenangkan sampai tuntas","Menghina lawan debat dengan kata-kata tajam supaya ia malu lalu berhenti membalas, sehingga perdebatan cepat berakhir"],answer:0,explain:"Menarik diri dari perdebatan yang tidak sehat adalah pilihan yang matang, bukan kekalahan.",hint:"Sampaikan sekali lalu berhenti bila tak sehat, atau balas sampai menang / menghina?"},
{n:77,type:"mcq",micro:"Menulis instruksi yang tahan salah",q:"Instruksi tertulis yang baik untuk dilakukan orang tanpa kamu di sana:",options:["Satu paragraf umum tanpa langkah jelas, supaya pembaca bebas menyesuaikan dengan keadaannya","Langkah bernomor + sangat spesifik + sebutkan apa yang TIDAK boleh + cara minta bantuan bila macet","'Lakukan yang biasa seperti sebelumnya ya, kamu tahu caranya kok, tak perlu kujelaskan rinci.'"],answer:1,explain:"Semakin sedikit kamu bisa mengoreksi secara langsung, semakin spesifik instruksi tertulis harus dibuat.",hint:"Bernomor + spesifik + larangan + jalur bantuan, atau 'yang biasa'?"},
{n:78,type:"mcq",micro:"Menilai nada pesanmu sendiri",q:"Trik memeriksa nada pesan sebelum kirim:",options:["Anggap nadanya oke karena niatmu baik, sehingga tak perlu dibaca ulang atau dipikirkan bagaimana pembaca menafsirkannya, lalu langsung kirim","Tambahkan banyak tanda seru di setiap kalimat agar terlihat bersemangat, walaupun isi pesannya sebenarnya berupa teguran","Baca dengan suara keras, atau bayangkan sahabatmu vs orang yang tidak menyukaimu membacanya — apakah keduanya menangkap maksud yang sama?"],answer:2,explain:"Niat baik tidak otomatis terbaca. Menguji dari beberapa sudut pandang menangkap nada yang tidak kamu maksudkan.",hint:"Uji dari beberapa sudut, atau anggap oke karena niat baik?"},
{n:79,type:"mcq",micro:"Komunikasi tertulis & bukti",q:"Kelebihan komunikasi tertulis untuk hal seperti kesepakatan atau instruksi:",options:["Ada catatan yang bisa dirujuk kembali, mengurangi 'katamu-katamu' — jadi rangkum kesepakatan penting secara tertulis","Tidak ada kelebihan, karena pesan tertulis sama saja dengan ucapan lisan dan tidak perlu dirangkum lagi","Tulisan lebih buruk dari lisan karena kesepakatan sebaiknya cukup diingat bersama tanpa dicatat oleh pihak mana pun"],answer:0,explain:"Untuk pembagian tugas, jadwal, & kesepakatan, menuliskannya menciptakan acuan bersama yang jelas.",hint:"Catatan yang bisa dirujuk, atau tak ada gunanya?"},
{n:80,type:"open",micro:"Menganalisis dua penulis pesan",q:"Penulis A: kirim 'p', tunggu balasan, lalu 'jadi ga besok', tanpa sapaan, sering ambigu, jarang membaca pesan orang sampai habis. Penulis B: satu pesan berisi sapaan + konteks + pertanyaan spesifik + penutup, membaca utuh sebelum membalas, menyesuaikan formalitas dengan penerima. Jelaskan mengapa Penulis B kemungkinan besar lebih efektif & menyenangkan diajak berkomunikasi (minimal 3 alasan), lalu sebut 2 kebiasaan A yang paling perlu diubah.",explain:"Jawaban baik memilih Penulis B dan memberi minimal 3 alasan (pesan lengkap sekali kirim = mudah dijawab; membaca utuh = jawaban nyambung; menyesuaikan formalitas = menghormati; kesan positif) lalu menyebut 2 kebiasaan A yang konkret untuk diubah (gabungkan jadi satu pesan berkonteks; baca utuh sebelum balas).",hint:"Bandingkan: pesan lengkap vs bertahap ambigu; baca utuh vs tidak; menyesuaikan formalitas vs tidak. Lalu 2 perbaikan konkret.",sample:"Penulis B lebih efektif dan menyenangkan diajak komunikasi. Alasan: (1) Pesan B lengkap dalam sekali kirim (sapaan + konteks + pertanyaan spesifik + penutup), jadi penerima bisa langsung memahami dan menjawab tanpa bolak-balik bertanya 'maksudnya apa'; pesan A yang bertahap dan ambigu ('p', 'jadi ga besok') memaksa penerima menebak dan menghabiskan waktu. (2) B membaca pesan orang sampai habis sebelum membalas, jadi jawabannya nyambung dan tidak mengulang hal yang sudah dijelaskan; A sering menjawab hal yang salah karena tidak membaca utuh. (3) B menyesuaikan formalitas dengan penerima, sehingga terasa menghormati baik ke teman maupun ke guru; A memakai gaya yang sama (dan minim) untuk semua orang, yang bisa terkesan kurang sopan ke pihak tertentu. (4) Pesan B yang terstruktur dan sopan juga membentuk kesan positif, penting saat berkomunikasi dengan orang yang belum kenal. Dua kebiasaan A yang paling perlu diubah: (a) berhenti mengirim 'p' / pesan bertahap tanpa isi — gabungkan jadi satu pesan lengkap dengan konteks dan pertanyaan spesifik; (b) selalu membaca pesan/utas sampai habis sebelum membalas."},
{n:81,type:"mcq",micro:"Kasus: menulis surat/pesan lamaran kegiatan",q:"Menulis pesan mendaftar jadi panitia acara ke kakak OSIS yang belum kamu kenal:",options:["Pesan sangat panjang yang berisi seluruh riwayat hidupmu dari kecil, supaya kakak OSIS mengenalmu dengan lengkap","Sapaan formal + perkenalan + kenapa kamu tertarik & apa yang bisa kamu bantu + kesediaan waktu + penutup + nama-kelas","'kak mau daftar panitia' saja tanpa sapaan, tanpa perkenalan, dan tanpa alasan, supaya singkat dan langsung ke inti"],answer:1,explain:"Pesan lamaran adalah kesan pertama: sopan, jelas, menyebut kontribusi & ketersediaan, tidak bertele-tele.",hint:"Perkenalan + kontribusi + ketersediaan + penutup, atau satu kalimat / autobiografi?"},
{n:82,type:"mcq",micro:"Kasus: pesan yang berpotensi disebarkan",q:"Kamu ingin mengeluh tentang seorang guru di grup chat kelas. Sebelum menulis:",options:["Tulis sepedas mungkin karena 'ini kan grup kita sendiri', jadi tak mungkin ada yang melaporkan atau menyebarkannya ke luar grup, dan guru tidak akan tahu","Tulis dulu keluhannya panjang lebar, lalu hapus cepat sebelum ada yang sempat membaca, supaya perasaanmu lega tanpa risiko, dan lanjut chat","Ingat pesan bisa di-screenshot & menyebar; kalau ada keluhan serius, sampaikan lewat jalur yang tepat, bukan gosip grup yang bisa merugikanmu & orang lain"],answer:2,explain:"Anggap semua yang kamu tulis bisa dibaca orang yang tidak kamu tuju. Keluhan serius punya jalur yang lebih tepat.",hint:"Pikirkan penyebaran & pakai jalur tepat, atau tulis pedas / tulis-hapus?"},
{n:83,type:"tf",micro:"Refleksi: teks butuh empati ekstra",q:"Benar atau Salah: Karena pembaca tidak bisa melihat wajahmu, komunikasi tertulis yang baik butuh usaha ekstra untuk membayangkan bagaimana kata-katamu akan terasa bagi orang lain.",answer:true,explain:"Empati di teks berarti: 'Kalau aku menerima pesan ini dalam suasana hati apa pun, apakah aku akan menangkap maksud & nada yang kuinginkan?'",hint:"Butuh empati ekstra, atau sama saja dengan tatap muka?"},
{n:84,type:"mcq",micro:"Kasus: menjawab pesan yang menuntut jawaban instan",q:"Seseorang mengirim serangkaian pesan mendesak menuntut kamu memutuskan sekarang, padahal kamu belum bisa. Respons:",options:["'Aku butuh waktu mikir/cek dulu. Aku kabari paling lambat jam 8 malam ya.' — menetapkan batas & memberi waktu pasti","Memutuskan asal-asalan dengan cepat demi menghentikan pesan-pesan itu, walau belum sempat memikirkannya baik-baik","Mengabaikan pesannya sampai ia berhenti sendiri, tanpa mengatakan apa-apa dan tanpa menetapkan kapan menjawab"],answer:0,explain:"Kamu boleh menolak tekanan waktu buatan. Menyebut kapan kamu akan menjawab itu jelas & hormat.",hint:"Minta waktu + sebut kapan, atau putuskan asal / abaikan?"},
{n:85,type:"order",micro:"Menulis pesan meminta bantuan yang efektif",q:"Urutkan cara menulis pesan minta bantuan agar orang mudah & mau membantu.",items:["Sapa & sebut konteks singkat: apa yang kamu kerjakan/hadapi","Sebutkan apa yang sudah kamu coba sendiri","Ajukan pertanyaan/permintaan yang spesifik & terbatas","Beri ruang untuk menolak & ucapkan terima kasih"],answer:[0,1,2,3],explain:"Konteks → usaha sendiri → permintaan spesifik → ruang menolak + terima kasih. Ini menghormati waktu & kemampuan penolong.",hint:"Apa yang ditunjukkan sebelum meminta agar orang tahu kamu sudah berusaha?"},
{n:86,type:"mcq",micro:"Kasus: nada beda antar budaya/generasi",q:"Titik di akhir pesan singkat ('Oke.') terasa netral bagi sebagian orang tapi 'dingin/marah' bagi sebagian lain. Sikap bijak:",options:["Berhenti memakai tanda baca dalam semua pesan supaya tak ada yang salah paham tentang nada tulisanmu, dan menulis dengan huruf kecil semua","Sadari norma nada berbeda antar orang & kelompok; kalau ragu apakah pesanmu terbaca dingin, tambahkan sedikit kehangatan atau perjelas","Berasumsi bahwa semua pembaca membaca pesan dengan cara yang persis sama dengan caramu, jadi tak perlu diubah lagi di masa depan"],answer:1,explain:"Konvensi digital (titik, 'k', jeda balas) bermakna beda antar kelompok. Kepekaan & sedikit kehangatan mengurangi salah baca.",hint:"Sadar perbedaan & tambah kehangatan, atau berasumsi sama?"},
{n:87,type:"tf",micro:"Pesan pertama = kesan pertama",q:"Benar atau Salah: Saat menghubungi orang atau lembaga yang belum mengenalmu, isi & gaya pesan pertamamu tidak memengaruhi bagaimana mereka menanggapimu.",answer:false,explain:"Sebaliknya, pesan pertamamu adalah kesan pertama: yang jelas, sopan, & lengkap membuat orang lebih mau membantu; yang asal sering diabaikan atau dianggap tidak serius.",hint:"Pesan pertama = kesan pertama, atau tidak berpengaruh?"},
{n:88,type:"mcq",micro:"Kasus: menyampaikan penghargaan tertulis",q:"Setelah dibantu banyak oleh seseorang, mengirim pesan terima kasih yang berkesan:",options:["'Makasih ya.' saja, singkat tanpa menyebut apa yang sudah dilakukan atau dampaknya bagimu, supaya tidak terdengar berlebihan atau dibuat-buat oleh penerimanya","Tidak mengucapkan apa-apa kepada orang yang membantu, karena ia sudah tahu kamu berterima kasih dari sikapmu tanpa perlu diucapkan atau ditulis, dan itu dianggap lebih tulus","Spesifik: sebut apa yang mereka lakukan & dampaknya bagimu ('Makasih ya udah luangin waktu jelasin materi statistik kemarin — aku jadi bisa ngerjain ulangannya dengan tenang')"],answer:2,explain:"Terima kasih yang menyebut hal spesifik & dampaknya terasa jauh lebih tulus & membuat orang senang membantu lagi.",hint:"Spesifik + dampak, atau 'makasih ya' / diam?"},
{n:89,type:"mcq",micro:"Kasus: pesan yang salah paham menyebar",q:"Sebuah pesanmu di grup disalahpahami & beberapa orang tersinggung. Langkah:",options:["Klarifikasi dengan tenang di grup: 'Maaf, sepertinya pesanku tadi kurang jelas. Yang kumaksud sebenarnya...'; kalau ada yang terluka, minta maaf tulus","Diam saja & berharap kesalahpahaman itu mereda sendiri dengan berjalannya waktu, tanpa perlu menjelaskan apa-apa di dalam grup","Menyalahkan mereka karena 'salah baca' pesanmu & menyuruh mereka membaca lebih teliti lain kali sebelum menyimpulkan sesuatu"],answer:0,explain:"Ambil tanggung jawab atas kejelasan pesanmu, luruskan maksud, & minta maaf bila ada yang terluka — lebih cepat memulihkan.",hint:"Klarifikasi + minta maaf bila perlu, atau diam / menyalahkan pembaca?"},
{n:90,type:"open",micro:"Kasus menyeluruh: panduan komunikasi digital kelas",q:"Kelasmu akan membuat grup chat resmi. Sebagai admin, tulis panduan singkat berisi minimal 6 aturan komunikasi digital yang sehat untuk grup itu, dengan alasan tiap aturan.",explain:"Jawaban baik memuat minimal 6 aturan konkret dengan alasan, mencakup ide inti bab: pesan jelas berkonteks (bukan 'p'), satu pesan rapi (anti-spam), nada sopan + hati-hati sarkasme, anti-hoaks/spam/pesan berantai, hormati waktu + akui pesan, larangan sebar screenshot pribadi + anti-perundungan (jejak permanen), klarifikasi + tidak melanjutkan debat panas, membaca utuh sebelum membalas.",hint:"Turunkan tiap prinsip bab jadi aturan grup: kejelasan, anti-spam, nada, anti-hoaks, hormati waktu, privasi & anti-bully, penanganan salah paham, baca utuh.",sample:"Panduan grup kelas: (1) Isi pesan dengan jelas: sebut konteks + inti + siapa yang perlu bertindak; hindari 'p' atau pesan bertahap tanpa isi — supaya tidak membuang waktu dan tidak ambigu. (2) Satu topik = satu pesan yang rapi (boleh poin bernomor), jangan spam pesan pendek beruntun — supaya notifikasi tidak mengganggu dan mudah dibaca ulang. (3) Jaga nada: pakai 'tolong'/'makasih', kalimat lengkap, tanpa huruf kapital semua; hati-hati dengan sarkasme karena nada tidak terdengar di teks. (4) Grup ini untuk keperluan kelas; hindari menyebarkan hoaks (cek dulu sebelum forward), spam, dan pesan berantai. (5) Hormati waktu: untuk hal tidak mendesak, kirim di jam wajar; jangan menuntut balasan instan; kalau belum sempat menjawab hal penting, akui dulu ('nanti kubalas'). (6) Jangan menyebarkan screenshot percakapan pribadi anggota tanpa izin, dan jangan memakai grup untuk mempermalukan atau merundung siapa pun — ini bisa melukai dan meninggalkan jejak permanen. (7) Kalau ada salah paham, klarifikasi dengan tenang dan minta maaf bila menyakiti; jangan lanjutkan debat yang memanas di grup — bawa ke pembicaraan langsung. (8) Baca pesan/utas sampai habis sebelum membalas supaya jawaban nyambung. Admin akan mengingatkan dengan sopan bila ada yang melanggar, dan pelanggaran serius (perundungan, penyebaran data pribadi) dibicarakan dengan wali kelas."},
{n:91,type:"mcq",micro:"Kasus: perbedaan japri vs grup",q:"Kritik atau teguran ke satu anggota kelompok sebaiknya disampaikan...",options:["Lewat orang ketiga yang dianggap lebih bijak, supaya kamu tidak berhadapan langsung dengan orangnya","Lewat japri (pesan pribadi), bukan di grup — koreksi publik mempermalukan; apresiasi boleh di grup","Di grup agar anggota lain ikut belajar, karena koreksi di depan umum membuat semua lebih disiplin"],answer:1,explain:"'Puji di depan umum, koreksi secara pribadi' berlaku juga di dunia digital.",hint:"Koreksi lewat japri, atau umumkan di grup?"},
{n:92,type:"tf",micro:"Refleksi: media disesuaikan dengan pesan",q:"Benar atau Salah: Bagian dari komunikasi yang baik adalah memilih media yang tepat — teks untuk info & koordinasi cepat, panggilan/tatap muka untuk hal emosional, kompleks, atau sensitif.",answer:true,explain:"Memaksakan percakapan sulit lewat teks, atau mengoordinasi jadwal lewat panggilan panjang, sama-sama kurang efisien.",hint:"Satu media untuk semua, atau sesuaikan media dengan isi?"},
{n:93,type:"mcq",micro:"Kasus: menulis saat lelah/mengantuk",q:"Kamu perlu menulis pesan penting tapi sedang sangat lelah. Sikap:",options:["Kirim apa adanya karena lelah bukan alasan untuk menunda menyampaikan perasaan yang jujur","Tunda sampai beberapa minggu kemudian, lalu kirim ketika kamu sudah benar-benar lupa kejadian itu","Tulis draf kalau perlu, tapi jangan kirim final; baca ulang besok pagi saat segar sebelum mengirim"],answer:2,explain:"Kejernihan & nada tulisanmu menurun saat lelah. Menunda pengiriman final ke saat segar mencegah kesalahan.",hint:"Draf sekarang, kirim setelah segar — atau kirim apa adanya?"},
{n:94,type:"mcq",micro:"Kasus: pesan grup yang butuh keputusan cepat",q:"Grup perlu memutuskan sesuatu cepat lewat chat. Cara admin memfasilitasi:",options:["Tulis pilihan dengan jelas (A/B/C), sebut tenggat keputusan, minta tiap orang memilih dengan format seragam, lalu rangkum hasilnya","Membiarkan diskusi mengalir tanpa struktur dan tenggat, supaya anggota bebas berpendapat sepanjang hari dan tak terburu-buru","Memutuskan sendiri tanpa bertanya kepada anggota, lalu mengumumkan hasilnya ke grup seolah semua menyetujui tadi"],answer:0,explain:"Struktur (pilihan jelas + tenggat + format jawaban seragam + rangkuman) membuat keputusan grup lewat chat bisa cepat & jelas.",hint:"Pilihan jelas + tenggat + rangkum, atau mengalir tanpa struktur?"},
{n:95,type:"tf",micro:"Komunikasi digital = keterampilan penting",q:"Benar atau Salah: Kemampuan berkomunikasi tertulis dengan jelas & sopan makin tidak relevan, karena hampir semua urusan penting sekarang dibicarakan secara lisan.",answer:false,explain:"Sebaliknya, banyak koordinasi sekolah, kegiatan, & kelak pekerjaan justru dilakukan lewat pesan & email. Orang yang menulis jelas & sopan lebih dipercaya tugas & lebih jarang salah paham.",hint:"Makin penting, atau makin tidak relevan?"},
{n:96,type:"mcq",micro:"Kasus: refleksi setelah salah paham chat",q:"Setelah pesanmu menimbulkan salah paham, refleksi yang membangun:",options:["Tidak memikirkannya karena pesan sudah terkirim dan tak bisa ditarik, jadi percuma dievaluasi lagi","'Kata/kalimat mana yang ambigu? Nada apa yang tanpa sengaja terkirim? Bagaimana aku akan menulisnya lain kali?'","'Dasar dia yang lemot dan sensitif, salahnya sendiri tidak paham maksud pesanku yang jelas itu.'"],answer:1,explain:"Menelaah titik lemah pesanmu sendiri mengubah kesalahpahaman menjadi pelajaran untuk tulisan berikutnya.",hint:"Telaah pesanmu, atau menyalahkan pembaca?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti komunikasi tertulis & digital:",options:["Makin panjang dan santai pesannya makin baik, karena penerima punya banyak waktu membaca semuanya; nada dan formalitas tak perlu diperiksa, pesan tak perlu dibaca ulang, dan satu media cukup untuk segala urusan, sehingga lebih hemat waktu","Balas semua pesan dalam hitungan detik tanpa dibaca ulang, pakai media apa saja yang paling cepat, dan anggap pesanmu terlupakan orang setelah dibaca, sehingga tak perlu hati-hati menulis hal sensitif, karena itu efisien","Tulis dengan tujuan jelas & pembaca di benak; sampaikan inti di depan, ringkas & terstruktur; jaga nada (teks kehilangan nada suara); sesuaikan formalitas; baca ulang sebelum kirim; pilih media tepat; & ingat pesan bisa disimpan & disebar"],answer:2,explain:"Ringkasan: tujuan + pembaca; inti di depan + ringkas + terstruktur; jaga nada; formalitas sesuai penerima; baca ulang; media tepat; pesan itu permanen.",hint:"Tujuan & pembaca, inti di depan, nada, formalitas, baca ulang, media tepat, permanen — rangkai."},
{n:98,type:"tf",micro:"Refleksi: menulis untuk pembaca",q:"Benar atau Salah: Ukuran keberhasilan sebuah pesan bukan seberapa lengkap kamu menuangkan isi kepalamu, melainkan seberapa tepat pembaca menangkap maksudmu & tahu apa yang perlu mereka lakukan.",answer:true,explain:"Komunikasi berpusat pada penerima. Pesan indah yang tidak dipahami atau salah tafsir adalah pesan yang gagal.",hint:"Menuangkan isi kepala, atau pembaca menangkap tepat?"},
{n:99,type:"mcq",micro:"Kasus: memulai memperbaiki komunikasi digitalmu",q:"Cara termudah mulai memperbaiki kebiasaan menulis pesanmu:",options:["Minggu ini, sebelum mengirim pesan penting, berhenti 5 detik & baca ulang sekali dari sudut penerima — apakah jelas? nadanya oke?","Menunggu sampai kamu menjadi penulis hebat dan berpengalaman dulu, baru memperhatikan cara menulis pesanmu kepada orang lain","Menghindari mengirim pesan, terutama yang penting, supaya tak ada risiko salah tulis atau disalahpahami oleh penerimanya"],answer:0,explain:"Kebiasaan kecil 'baca ulang sekali sebelum kirim' menangkap sebagian besar kesalahan & salah nada.",hint:"Baca ulang sebelum kirim, atau menunggu jadi hebat / menghindar?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi komunikasi digital",q:"Tulis 'aturan pribadi komunikasi tertulis & digital' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: tetapkan tujuan, inti di depan + terstruktur, jaga nada (anti kapital/sarkasme), sesuaikan formalitas, baca ulang + jangan kirim saat emosi/lelah, pilih media sesuai isi, ingat permanen + privasi, akui pesan yang belum dibalas.",hint:"Ambil satu pelajaran tiap fase — tujuan, inti di depan, nada, formalitas, baca ulang/jeda, media tepat, permanen/privasi — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Sebelum menulis pesan penting, aku tetapkan tujuannya: apa yang aku ingin pembaca tahu atau lakukan — supaya pesanku terarah. (2) Aku taruh inti/permintaan di depan, lalu detail; pakai kalimat lengkap dan poin bila banyak hal — karena pembaca sering memindai dan inti bisa terkubur. (3) Aku jaga nada: pakai sapaan + 'tolong'/'makasih', hindari kapital semua dan sarkasme — karena teks kehilangan nada suara dan mudah terbaca kasar. (4) Aku sesuaikan gaya dengan penerima: formal ke guru/panitia, santai ke teman — karena menyesuaikan itu bentuk menghormati. (5) Aku baca ulang sekali dari sudut penerima sebelum mengirim, dan tidak mengirim pesan final saat sedang marah atau sangat lelah — karena pesan terkirim tidak bisa ditarik. (6) Untuk hal emosional, sensitif, atau kompleks, aku memilih bicara langsung/telepon; teks kupakai untuk info dan koordinasi. (7) Aku ingat pesan bisa di-screenshot dan disebar, jadi aku tidak menulis hal yang akan kusesali bila dibaca orang lain, dan tidak menyebarkan screenshot percakapan pribadi orang tanpa izin. (8) Kalau belum sempat menjawab pesan penting, aku akui dulu ('aku baca ya, nanti kubalas')."},
];
